def main(data: str) -> dict:
    import json
    from datetime import datetime, timedelta

    def parse_relative_date(date_str: str) -> str:
        if not date_str or date_str.strip() == "":
            return datetime.now().strftime("%Y-%m-%d")

        date_str = date_str.strip()
        today = datetime.now()

        if date_str == "今天":
            return today.strftime("%Y-%m-%d")
        elif date_str == "明天":
            return (today + timedelta(days=1)).strftime("%Y-%m-%d")
        elif date_str == "后天":
            return (today + timedelta(days=2)).strftime("%Y-%m-%d")
        else:
            for fmt in ["%Y-%m-%d", "%Y/%m/%d", "%m-%d", "%m/%d"]:
                try:
                    parsed = datetime.strptime(date_str, fmt)
                    if "%Y" not in fmt:
                        parsed = parsed.replace(year=today.year)
                    return parsed.strftime("%Y-%m-%d")
                except ValueError:
                    continue
            return today.strftime("%Y-%m-%d")

    try:
        input_data = json.loads(data)
    except json.JSONDecodeError:
        return {"city": "", "date": "", "is_valid": False, "error_msg": "输入数据格式错误"}

    city = input_data.get("city", "").strip()
    date_raw = input_data.get("date", "")
    date = parse_relative_date(date_raw)

    is_valid = len(city) > 0 and len(city) <= 50
    error_msg = "城市名称不能为空" if not is_valid else ""

    return {"city": city, "date": date, "is_valid": is_valid, "error_msg": error_msg}

def main(raw_weather: dict, is_error: int) -> dict:
    def safe_get(data: dict, keys: list, default=None):
        result = data
        for key in keys:
            if isinstance(result, dict):
                result = result.get(key)
                if result is None:
                    return default
            else:
                return default
        return result

    if is_error == 1 or not raw_weather:
        return {"weather_info": {}, "has_data": False}

    try:
        weather_info = {
            "city": safe_get(raw_weather, ["city", "name"], ""),
            "date": safe_get(raw_weather, ["date"], ""),
            "temperature": {
                "current": float(safe_get(raw_weather, ["temperature", "current"], 25)),
                "min": float(safe_get(raw_weather, ["temperature", "min"], 20)),
                "max": float(safe_get(raw_weather, ["temperature", "max"], 30))
            },
            "condition": safe_get(raw_weather, ["condition", "text"], "晴"),
            "humidity": int(safe_get(raw_weather, ["humidity"], 60)),
            "wind_speed": float(safe_get(raw_weather, ["wind", "speed"], 3)),
            "wind_direction": str(safe_get(raw_weather, ["wind", "direction"], "东风")),
            "air_quality": str(safe_get(raw_weather, ["air_quality", "level"], "良")),
            "uv_index": {"value": 8, "level": "强"},
            "sunrise": str(safe_get(raw_weather, ["sun", "rise"], "06:00")),
            "sunset": str(safe_get(raw_weather, ["sun", "set"], "18:30")),
            "tips": ["注意防晒", "适宜户外活动"]
        }
        return {"weather_info": weather_info, "has_data": True}
    except Exception as e:
        return {"weather_info": {}, "has_data": False}

